/**
 * @name XPath injection
 * @description Constructing XPath expressions from user input can lead to XPath injection attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xpath-injection
 * @tags security
 *        external/cwe/cwe-643
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module XPathInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        // lxml xpath() method calls
        call.getFunction().(DataFlow::AttrRead).getAttributeName() = "xpath" or
        // etree.XPath() constructor
        call = API::moduleImport("lxml").getMember("etree").getMember("XPath").getACall() or
        // etree.XPathEvaluator() constructor
        call = API::moduleImport("lxml").getMember("etree").getMember("XPathEvaluator").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module XPathInjectionFlow = TaintTracking::Global<XPathInjectionConfig>;
import XPathInjectionFlow::PathGraph

from XPathInjectionFlow::PathNode source, XPathInjectionFlow::PathNode sink
where XPathInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XPath expression may be vulnerable to injection from $@.", source.getNode(), "user input"

/**
 * @name Command injection
 * @description Executing system commands with user-controlled data can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SystemCommandExecution cmd |
      sink = cmd.getCommand()
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"
